                        raise ValueError
                    i += 1
                    skip_ws()
                    val = parse_value()
                    items[key] = val
                    skip_ws()
                    if i >= n:
                        raise ValueError
                    if data[i] == ',':
                        i += 1
                        continue
                    elif data[i] == '}':
                        i += 1
                        return items
                    else:
                        raise ValueError
