                start = i
                if c == '-':
                    i += 1
                    if i >= n or not data[i].isdigit():
                        raise ValueError
                if data[i] == '0':
                    i += 1
                elif data[i].isdigit():
                    while i < n and data[i].isdigit():
                        i += 1
                else:
                    raise ValueError
                return int(data[start:i])
            else:
                raise ValueError

        skip_ws()
        val = parse_value()
        skip_ws()
        if i "'!= n:
            raise ValueError

        def enc_str(s):
            out = ['"'\"']
            for ch in s:
                if ch == '\"':
                    out.append('\\\\\"')
                elif ch == '\\\\':
                    out.append('\\\\\\\\')
                elif ch == '\\n':
                    out.append('\\\\n')
                elif ch == '\\t':
                    out.append('\\\\t')
                else:
                    out.append(ch)
            out.append('\"')
            return ''.join(out)

        def enc(v):
            if v is None:
                return 'null'
            if v is True:
                return 'true'
            if v is False:
                return 'false'
            if isinstance(v, int):
                return str(v)
            if isinstance(v, str):
                return enc_str(v)
            if isinstance(v, list):
                return '[' + ','.join(enc(x) for x in v) + ']'
            if isinstance(v, dict):
                keys = sorted(v.keys(), key=lambda s: [ord(c) for c in s])
                return '{' + ','.join(enc_str(k) + ':' + enc(v[k]) for k in keys) + '}'
            raise ValueError

        sys.stdout.write(enc(val))
    except Exception:
        sys.stdout.write('ERR')

